#include <bits/stdc++.h>
using namespace std;
#define ll long long

void solve(){
    int n;
    cin>>n;
    vector<ll> a(3*n);
    for(auto &x : a) cin>>x;
    sort(a.rbegin(),a.rend());
    vector<ll> p(3*n+1,0);
    for(int i = 0;i<3*n;i++) p[i+1] = p[i]+a[i];
    ll ans = 0;
    for(int c1 = 0;c1<=n;c1++){
        int maxc2 = n-c1;
        int low = 0, high = maxc2;
        while(low<high){
            int mid = (low+high+1)/2;
            int c2 = mid-1;
            int quo = c1+2*c2;
            int roo = 3*n-2*c1-c2;
            ll dif;
            if(c2==maxc2) dif = LLONG_MIN;
            else dif = a[quo]+a[quo+1]-3LL*a[roo-1];
            if(dif>=0) low = mid;
            else high = mid-1;
        }
        for(int c2 : {low,min(low+1,maxc2)}){
            int quo = c1+2*c2;
            int roo = 3*n-2*c1-c2;
            ll curr = 6LL * p[c1]+ 4LL *(p[quo]-p[c1])+ 3LL * (p[roo]-p[quo]);
            ans = max(ans,curr);
        }
    }
    cout<<ans<<'\n';
}
int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	cin>>t;
	while(t--) solve();
	return 0;

}
